import assert from 'node:assert/strict'
import { spawnSync, spawn } from 'node:child_process'
import { mkdtempSync, readFileSync, writeFileSync, mkdirSync, existsSync } from 'node:fs'
import { createConnection, createServer } from 'node:net'
import { setTimeout as delay } from 'node:timers/promises'

const root = '/home/baptiste/itrocks/showtime'
const recipe = `${root}/node_modules/@itrocks/property-select/docs/orchestration/environment`
const directory = mkdtempSync('/tmp/property-select-final-independent-')
const ports = [13471, 13472, 13473]
const env = { ...process.env, PS_ENV_DIRECTORY: directory, PS_DATABASE_PORT: String(ports[0]),
 PS_APP_PORT: String(ports[1]), PS_STANDALONE_PORT: String(ports[2]) }
const report = { directory, ports, timestamp: new Date().toISOString(), checks: [], defects: [] }
const listening = port => new Promise(resolve => {
 const socket = createConnection({ host: '127.0.0.1', port })
 socket.on('connect', () => { socket.destroy(); resolve(true) })
 socket.on('error', () => resolve(false))
})
async function until(check) {
 const deadline = Date.now() + 30000
 while (!await check()) { assert(Date.now() < deadline, 'Timeout'); await delay(100) }
}
function command(action, extra = {}, required = true) {
 const result = spawnSync(process.execPath, [`${recipe}/control.mjs`, action], {
  env: { ...env, ...extra }, cwd: root, encoding: 'utf8', timeout: 90000
 })
 report.checks.push({ action, directory: extra.PS_ENV_DIRECTORY ?? directory, status: result.status,
  stdout: result.stdout, stderr: result.stderr })
 if (required) assert.equal(result.status, 0, result.stderr)
 return result
}
function sql(query) {
 const result = spawnSync('mysql', ['--no-defaults', `--socket=${directory}/mysql.sock`, '-u', 'root',
  '--batch', '--skip-column-names', '-e', query], { encoding: 'utf8', timeout: 10000 })
 assert.equal(result.status, 0, result.stderr)
 return result.stdout.trim()
}
const inheritedPorts = [13316,13317,13318,13319,13320,13321,13322,13323,13424,13425,13426]
const inherited = await Promise.all(inheritedPorts.map(listening))
for (const port of ports) await new Promise((resolve,reject) => {
 const server = createServer().once('error', reject)
 server.listen(port,'127.0.0.1',() => server.close(resolve))
})
console.log(`New resources: ${directory}; ports ${ports}`)
try {
 for (const cycle of [1,2]) {
  command('database')
  await until(async () => {
   const ping = spawnSync('mysqladmin',['--no-defaults',`--socket=${directory}/mysql.sock`,'-u','root','ping'],
    {encoding:'utf8',timeout:5000})
   return ping.status === 0
  })
  if (cycle === 1) command('reset')
  const identity = sql('SELECT @@datadir, @@socket, @@pid_file, @@port, @@server_uuid, @@general_log')
  const uuid = identity.split('\t')[4]
  if (cycle === 1) report.uuid = uuid
  else assert.equal(uuid, report.uuid)
  report.checks.push({ name:'instance-identity', cycle, identity })
  const foreign = `${directory}/foreign-mysql`
  mkdirSync(foreign,{recursive:true})
  writeFileSync(`${foreign}/mysql.pid`,readFileSync(`${directory}/mysql.pid`))
  const refused = command('stop',{PS_ENV_DIRECTORY:foreign},false)
  assert.notEqual(refused.status,0)
  assert.match(refused.stderr,/not the owned MySQL instance/)
  assert(await listening(ports[0]))
  command('app'); command('standalone')
  await until(async () => (await Promise.all(ports.map(listening))).every(Boolean))
  command('status')
  if (cycle === 1) {
   const browserScript = readFileSync('/tmp/verify-property-select-environment.cjs','utf8')
    .replaceAll('/tmp/showtime-property-select-verify',directory)
    .replaceAll('13323',String(ports[0])).replaceAll('13321',String(ports[1]))
    .replaceAll('13322',String(ports[2]))
   writeFileSync(`${directory}/browser.cjs`,browserScript)
   const result = spawnSync(process.execPath,[`${directory}/browser.cjs`],{encoding:'utf8',timeout:90000,cwd:root})
   writeFileSync(`${directory}/browser.stdout`,result.stdout)
   writeFileSync(`${directory}/browser.stderr`,result.stderr)
   assert.equal(result.status,0,result.stderr)
   report.checks.push({name:'independent-browser-sql-touch',status:result.status})
   const innocent = spawn(process.execPath,['-e','setInterval(() => {}, 1000)'],{stdio:'ignore'})
   try {
    const foreignPid = `${directory}/foreign-node`
    mkdirSync(foreignPid)
    for (const owner of ['app','standalone']) {
     writeFileSync(`${foreignPid}/${owner}.pid`,String(innocent.pid))
     const rejection = command(`stop-${owner}`,{PS_ENV_DIRECTORY:foreignPid},false)
     assert.notEqual(rejection.status,0)
     assert.match(rejection.stderr,/not the owned/)
     process.kill(innocent.pid,0)
    }
   } finally { innocent.kill('SIGTERM') }
   for (const [owner,port] of [['app',ports[1]],['standalone',ports[2]]]) {
    const foreignDirectory = `${directory}/foreign-${owner}`
    mkdirSync(foreignDirectory)
    const pid = readFileSync(`${directory}/${owner}.pid`,'utf8').trim()
    writeFileSync(`${foreignDirectory}/${owner}.pid`,pid)
    const result = command(`stop-${owner}`,{PS_ENV_DIRECTORY:foreignDirectory},false)
    await delay(300)
    const stillAlive = await listening(port)
    report.checks.push({name:'same-launcher-foreign-directory',owner,pid,status:result.status,stillAlive})
    if (result.status === 0 && !stillAlive) report.defects.push({
     name:'foreign-environment-process-stopped',owner,pid,foreignDirectory,port,
     expected:'Reject a PID belonging to a different PS_ENV_DIRECTORY and retain the listener',
     observed:'Exit 0 and the other environment listener closes'
    })
   }
  }
  command('stop')
  await until(async () => !(await Promise.all(ports.map(listening))).some(Boolean))
  assert(!existsSync(`${directory}/mysql.sock`)); assert(!existsSync(`${directory}/mysql.pid`))
  command('stop')
  assert.match(readFileSync(`${directory}/mysql.log`,'utf8'),/Shutdown complete/)
  const journal = readFileSync(`${directory}/queries.log`,'utf8')
  assert.match(journal,/Query\tshutdown/i)
  if (cycle === 1) {
   assert.match(journal,/independent-environment-verification/)
   assert.match(journal,/SELECT id, `name` FROM `country` LIMIT 50/)
  }
  console.log(`Cycle ${cycle}: owned MySQL administrative shutdown and repeated stop PASS`)
 }
 assert.deepEqual(await Promise.all(inheritedPorts.map(listening)),inherited)
 report.inherited = { ports:inheritedPorts, before:inherited, after:await Promise.all(inheritedPorts.map(listening)) }
 report.verdict = report.defects.length ? 'NEEDS_FIX' : 'PASS'
} finally {
 if (existsSync(`${directory}/mysql.pid`)) command('stop')
 writeFileSync(`${directory}/lifecycle-results.json`,JSON.stringify(report,null,2)+'\n')
 console.log(JSON.stringify({directory,uuid:report.uuid,verdict:report.verdict,defects:report.defects},null,2))
}

const assert = require('node:assert/strict')
const fs = require('node:fs/promises')
const { createRequire } = require('node:module')
const { chromium } = require('/home/baptiste/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules/playwright')
const requireApp = createRequire('/home/baptiste/itrocks/showtime/package.json')
const { createConnection } = requireApp('mariadb')
const out = '/tmp/property-select-final-independent-M9yqWL'
const report = { timestamp: new Date().toISOString(), scenarios: [], browserErrors: [], failedRequests: [] }
const delay = ms => new Promise(resolve => setTimeout(resolve, ms))
async function sql() {
 const connection = await createConnection({host:'127.0.0.1',port:13471,user:'root',password:'',database:'property_select_recipe'})
 try {
  const rows = await connection.query(`SELECT /* independent-environment-verification */ i.number,c.name,cy.name AS city,i.amount,i.issued_at,i.note,i.active FROM ps_invoice i LEFT JOIN ps_customer c ON c.id=i.id_customer LEFT JOIN ps_address a ON a.id=c.id_address LEFT JOIN ps_city cy ON cy.id=a.id_city ORDER BY i.id`)
  assert.deepEqual(rows.map(r=>r.number),['REC-001','REC-002','REC-003','REC-004'])
  assert.equal(rows[0].city,'Recipe Paris'); assert.equal(rows[2].city,null); assert.equal(rows[3].name,null)
  assert.equal(String(rows[0].amount),'12.34'); assert(rows[0].issued_at instanceof Date)
  assert.equal(rows[0].note,null); assert.equal(rows[2].note,''); assert.deepEqual(rows.map(r=>r.active),[1,0,1,1])
  const filtered = await connection.query('SELECT i.number FROM ps_invoice i JOIN ps_customer c ON c.id=i.id_customer WHERE c.name=? ORDER BY i.id LIMIT 1',['Recipe Alice'])
  assert.equal(filtered[0].number,'REC-001')
  report.scenarios.push({name:'fresh-mysql',verdict:'PASS',roots:rows.length})
 } finally { await connection.end() }
}
async function capability(page) { return page.evaluate(()=>({width:innerWidth,height:innerHeight,touch:navigator.maxTouchPoints,coarse:matchMedia('(pointer: coarse)').matches,hover:matchMedia('(hover: hover)').matches})) }
async function events(page) { return JSON.parse(await page.locator('#events').textContent()) }
async function watch(page) {
 page.on('pageerror',error=>report.browserErrors.push(error.message))
 page.on('console',message=>{if(['error','warning'].includes(message.type())) report.browserErrors.push(message.text())})
 page.on('requestfailed',request=>report.failedRequests.push({url:request.url(),error:request.failure()?.errorText}))
}
(async()=>{
 await sql()
 let browser = await chromium.launch({headless:true,chromiumSandbox:true})
 try {
  report.browser=browser.version()
  const desktop = await browser.newContext({hasTouch:false,viewport:{width:1280,height:720}})
  const page = await desktop.newPage(); await watch(page)
  for(const [width,height] of [[1280,720],[390,844],[844,390]]) {
   await page.setViewportSize({width,height}); assert.equal((await page.goto('http://127.0.0.1:13472/country')).status(),200)
   await page.locator('table.objects').waitFor(); const text=await page.locator('table.objects').innerText()
   assert(text.includes('Recipe France')); assert(text.includes('Recipe United Kingdom'))
   const cap=await capability(page); assert.equal(cap.width,width); assert.equal(cap.height,height)
   await page.screenshot({path:`${out}/application-${width}.png`,fullPage:true})
   report.scenarios.push({name:'framework-navigation',cap,verdict:'PASS'})
  }
  assert.equal((await page.goto('http://127.0.0.1:13473/')).status(),200)
  assert((await page.locator('body').innerText()).includes('no selector implementation'))
  report.scenarios.push({name:'standalone-support',verdict:'PASS'})
  await page.goto('http://127.0.0.1:13473/touch-probe.html')
  const nonTouch=await capability(page); assert.equal(nonTouch.touch,0); assert.equal(nonTouch.coarse,false); assert.equal(nonTouch.hover,true)
  const box=await page.locator('#surface').boundingBox(); await page.mouse.click(box.x+30,box.y+50)
  const mouse=await events(page); assert(mouse.length>0); assert(mouse.every(e=>e.trusted && e.pointerType==='mouse' && !e.type.startsWith('touch')))
  let rejected=false; try {await page.touchscreen.tap(box.x+30,box.y+50)} catch(e) {rejected=/hasTouch/.test(e.message)}
  assert(rejected,'Tap must reject in a no-touch context')
  report.scenarios.push({name:'no-touch-negative-control',cap:nonTouch,events:mouse,rejected,verdict:'PASS'})
  await desktop.close()
  await browser.close()
  browser = await chromium.launch({headless:true,chromiumSandbox:true})
  const context=await browser.newContext({hasTouch:true,isMobile:true,viewport:{width:390,height:844}})
  const touchPage=await context.newPage(); await watch(touchPage)
  const session=await context.newCDPSession(touchPage)
  await touchPage.goto('http://127.0.0.1:13473/touch-probe.html')
  report.touchStartupEvents = await touchPage.locator('#events').textContent()
  const send=async(type,point)=>session.send('Input.dispatchTouchEvent',{type,touchPoints:point?[{id:7,...point}]:[]})
  for(const name of ['tap','long-press','drag','cancel','landscape-tap']) {
   if(name==='landscape-tap') await touchPage.setViewportSize({width:844,height:390})
   await touchPage.goto('http://127.0.0.1:13473/touch-probe.html')
   const cap=await capability(touchPage); assert(cap.touch>0); assert(cap.coarse); assert(!cap.hover)
   assert.equal(cap.width,name==='landscape-tap'?844:390); assert.equal(cap.height,name==='landscape-tap'?390:844)
   const b=await touchPage.locator('#surface').boundingBox(), point={x:Math.round(b.x+35),y:Math.round(b.y+50)}
   if(name.includes('tap')) await touchPage.touchscreen.tap(point.x,point.y)
   else {
    await send('touchStart',point)
    if(name!=='cancel') await delay(800)
    if(name==='drag') for(let i=1;i<=6;i++){await send('touchMove',{x:point.x+i*30,y:point.y+i*2}); await delay(25)}
    await send(name==='cancel'?'touchCancel':'touchEnd')
   }
   const log=await events(touchPage), pointers=log.filter(e=>e.type.startsWith('pointer'))
   assert(log.length>=4); assert(log.every(e=>e.trusted)); assert(pointers.every(e=>e.pointerType==='touch'), JSON.stringify({name,log}))
   assert.equal(log.filter(e=>e.type==='pointerdown').length,1); assert.equal(log.filter(e=>e.type==='touchstart').length,1)
   const end=name==='cancel'?'cancel':'up'; assert.equal(pointers.at(-1).type,`pointer${end}`)
   assert.equal(log.at(-1).type,name==='cancel'?'touchcancel':'touchend')
   const elapsed=pointers.at(-1).time-pointers[0].time, moved=Math.hypot(pointers.at(-1).x-pointers[0].x,pointers.at(-1).y-pointers[0].y)
   if(['long-press','drag'].includes(name)) assert(elapsed>=780)
   if(name==='drag'){assert(moved>=175); assert(log.some(e=>e.type==='touchmove')); assert(log.some(e=>e.type==='pointermove'))}
   else assert(moved<2)
   if(name==='cancel'){assert(!log.some(e=>e.type==='pointerup'||e.type==='touchend'))}
   await touchPage.screenshot({path:`${out}/independent-${name}.png`})
   report.scenarios.push({name,cap,elapsed,moved,events:log,verdict:'PASS'})
  }
  await touchPage.goto('http://127.0.0.1:13472/country')
  assert((await touchPage.locator('table.objects').innerText()).includes('Recipe France'))
  report.scenarios.push({name:'framework-touch-context',cap:await capability(touchPage),verdict:'PASS'})
  assert.deepEqual(report.browserErrors,[]); assert.deepEqual(report.failedRequests,[])
  report.verdict='PASS'
 } finally { await browser.close() }
 await fs.writeFile(`${out}/independent-results.json`,JSON.stringify(report,null,2)+'\n')
 console.log(JSON.stringify({...report,scenarios:report.scenarios.map(({events,...rest})=>rest)},null,2))
})().catch(error=>{console.error(error);process.exitCode=1})
